#include "dream/project/project.hpp"
#include <fstream>
namespace dream::project { static void q(std::ostream&o,const std::string&s){o<<'"';for(char c:s){if(c=='"'||c=='\\')o<<'\\';o<<c;}o<<'"';} bool save(const Project&p,const std::string&path,std::string*err){std::ofstream f(path);if(!f){if(err)*err="cannot open project";return false;}f<<"{\n  \"format\": "<<p.format<<",\n  \"name\": ";q(f,p.name);f<<",\n  \"start_scene\": ";q(f,p.start_scene);f<<"\n}\n";return(bool)f;} bool load(Project&p,const std::string&path,std::string*err){std::ifstream f(path);if(!f){if(err)*err="cannot open project";return false;}std::string s((std::istreambuf_iterator<char>(f)),{});if(s.find("\"format\"")==std::string::npos){if(err)*err="invalid project";return false;}auto read=[&](const char*k,std::string&v){auto a=s.find(k);if(a==std::string::npos)return; a=s.find('"',s.find(':',a)+1);auto b=s.find('"',a+1);if(a!=std::string::npos&&b!=std::string::npos)v=s.substr(a+1,b-a-1);};read("\"name\"",p.name);read("\"start_scene\"",p.start_scene);return true;} }
